package com.milano.quotation.logistics;

import tools.jackson.databind.node.ObjectNode;
import com.milano.quotation.audit.AuditService;
import com.milano.quotation.common.ApiResponse;
import com.milano.quotation.common.PageResponse;
import com.milano.quotation.idempotency.IdempotencyService;
import com.milano.quotation.security.QuotationPrincipal;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import java.util.List;import java.util.Map;import java.util.UUID;

@RestController @RequestMapping("/api/v1/logistics") @PreAuthorize("hasAuthority('PERM_logistics')") @Transactional
public class LogisticsController{
    private final LogisticsService logistics;private final LogisticsQueryService queries;private final LogisticsWorkbookService workbooks;private final AuditService audit;private final IdempotencyService idempotency;public LogisticsController(LogisticsService logistics,LogisticsQueryService queries,LogisticsWorkbookService workbooks,AuditService audit,IdempotencyService idempotency){this.logistics=logistics;this.queries=queries;this.workbooks=workbooks;this.audit=audit;this.idempotency=idempotency;}
    @GetMapping("/workspace")ApiResponse<LogisticsService.Workspace>workspace(){return ApiResponse.ok(logistics.workspace());}
    @GetMapping("/providers")ApiResponse<PageResponse<JsonNode>>providers(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size,@RequestParam(defaultValue="")String query,@RequestParam(required=false)Boolean enabled){return ApiResponse.ok(queries.providers(page,size,query,enabled));}
    @GetMapping("/channels")ApiResponse<PageResponse<JsonNode>>channels(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size,@RequestParam(defaultValue="")String query,@RequestParam(required=false)UUID providerId,@RequestParam(required=false)Boolean enabled){return ApiResponse.ok(queries.channels(page,size,query,providerId,enabled));}
    @GetMapping("/versions")ApiResponse<PageResponse<JsonNode>>versions(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size,@RequestParam(required=false)UUID channelId,@RequestParam(defaultValue="")String status){return ApiResponse.ok(queries.versions(page,size,channelId,status));}
    @GetMapping("/versions/{versionId}/rows")ApiResponse<PageResponse<JsonNode>>versionRows(@PathVariable UUID versionId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size,@RequestParam(defaultValue="")String countryCode,@RequestParam(defaultValue="")String query){return ApiResponse.ok(queries.versionRows(versionId,page,size,countryCode,query));}
    @GetMapping("/versions/{versionId}/issues")ApiResponse<PageResponse<JsonNode>>versionIssues(@PathVariable UUID versionId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){return ApiResponse.ok(queries.versionIssues(versionId,page,size));}
    @GetMapping("/versions/{versionId}/diff")ApiResponse<PageResponse<JsonNode>>versionDiff(@PathVariable UUID versionId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){return ApiResponse.ok(queries.versionDiff(versionId,page,size));}
    @PostMapping("/providers")ApiResponse<?>provider(@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){var existing=idempotency.existing(account(auth),"logistics-provider-create",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.addProvider(body);idempotency.save(account(auth),"logistics-provider-create",key,body,result);audit.record("logistics.provider-create","logistics-provider",result.path("id").asText(),"success",Map.of());return ApiResponse.ok(result);}
    @PostMapping("/channels")ApiResponse<?>channel(@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){var existing=idempotency.existing(account(auth),"logistics-channel-create",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.addChannel(body);idempotency.save(account(auth),"logistics-channel-create",key,body,result);audit.record("logistics.channel-create","logistics-channel",result.path("id").asText(),"success",Map.of());return ApiResponse.ok(result);}
    @PutMapping("/channels/{channelId}")ApiResponse<?>updateChannel(@PathVariable UUID channelId,@RequestBody ObjectNode body,@RequestHeader("If-Match")long version,Authentication auth){var result=logistics.updateChannel(channelId,body,version);audit.record("logistics.channel-update","logistics-channel",channelId.toString(),"success",Map.of("actor",account(auth)));return ApiResponse.ok(result);}
    @PatchMapping("/channels/{channelId}/status")ApiResponse<?>channelStatus(@PathVariable UUID channelId,@RequestBody ObjectNode body,@RequestHeader("If-Match")long version,Authentication auth){var result=logistics.setChannelEnabled(channelId,body.path("enabled").asBoolean(),version);audit.record("logistics.channel-status","logistics-channel",channelId.toString(),"success",Map.of("enabled",body.path("enabled").asBoolean(),"actor",account(auth)));return ApiResponse.ok(result);}
    @PostMapping("/channels/{channelId}/clone")ApiResponse<?>cloneChannel(@PathVariable UUID channelId,@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){body.put("sourceChannelId",channelId.toString());var existing=idempotency.existing(account(auth),"logistics-channel-clone",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.cloneChannel(channelId,body);idempotency.save(account(auth),"logistics-channel-clone",key,body,result);audit.record("logistics.channel-clone","logistics-channel",result.path("id").asText(),"success",Map.of("sourceChannelId",channelId));return ApiResponse.ok(result);}
    @DeleteMapping("/channels/{channelId}")ApiResponse<Void>deleteChannel(@PathVariable UUID channelId,Authentication auth){logistics.deleteChannel(channelId);audit.record("logistics.channel-delete","logistics-channel",channelId.toString(),"success",Map.of("actor",account(auth)));return ApiResponse.ok(null);}
    @PutMapping("/channels/{channelId}/manual-draft")ApiResponse<?>manualDraft(@PathVariable UUID channelId,@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){body.put("actor",account(auth));var existing=idempotency.existing(account(auth),"logistics-manual-draft",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.createManualDraft(channelId,body);idempotency.save(account(auth),"logistics-manual-draft",key,body,result);audit.record("logistics.manual-draft","logistics-version",result.path("id").asText(),"success",Map.of("channelId",channelId,"rows",body.path("rows").size()));return ApiResponse.ok(result);}
    @PostMapping("/channels/{channelId}/versions")ApiResponse<?>draft(@PathVariable UUID channelId,@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){body.put("channelId",channelId.toString());var existing=idempotency.existing(account(auth),"logistics-version-create",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.createDraft(channelId,body);idempotency.save(account(auth),"logistics-version-create",key,body,result);audit.record("logistics.import","logistics-version",result.path("id").asText(),"success",Map.of());return ApiResponse.ok(result);}
    @PostMapping(value="/channels/{channelId}/imports",consumes="multipart/form-data")ApiResponse<?>importWorkbook(@PathVariable UUID channelId,@RequestPart("file")MultipartFile file,@RequestParam(defaultValue="false")boolean replaceDraft,@RequestHeader("Idempotency-Key")String key,Authentication auth){var parsed=workbooks.parse(file,logistics.publishedRows(channelId));parsed.put("channelId",channelId.toString());parsed.put("importedBy",account(auth));parsed.put("publishedBy","");parsed.put("auditNote","");parsed.put("replaceDraft",replaceDraft);var existing=idempotency.existing(account(auth),"logistics-workbook-import",key,parsed);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=replaceDraft?logistics.createDraftReplacing(channelId,parsed,"被新上传的价格草稿终止"):logistics.createDraft(channelId,parsed);idempotency.save(account(auth),"logistics-workbook-import",key,parsed,result);audit.record("logistics.import","logistics-version",result.path("id").asText(),"success",Map.of("file",file.getOriginalFilename(),"rows",parsed.path("validRows").asInt()));return ApiResponse.ok(result);}
    @PostMapping(value="/providers/{providerId}/imports/preview",consumes="multipart/form-data")ApiResponse<?>previewProviderImports(@PathVariable UUID providerId,@RequestPart("files")List<MultipartFile> files){return ApiResponse.ok(previewBatch(providerId,files));}
    @PostMapping(value="/providers/{providerId}/imports",consumes="multipart/form-data")ApiResponse<?>importProviderFiles(@PathVariable UUID providerId,@RequestPart("files")List<MultipartFile> files,@RequestParam(defaultValue="false")boolean replaceDrafts,@RequestHeader("Idempotency-Key")String key,Authentication auth){var request=previewBatch(providerId,files);request.put("replaceDrafts",replaceDrafts);var existing=idempotency.existing(account(auth),"logistics-provider-batch-import",key,request);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.importProviderBatch(providerId,(tools.jackson.databind.node.ArrayNode)request.path("items"),account(auth),replaceDrafts);idempotency.save(account(auth),"logistics-provider-batch-import",key,request,result);for(var item:result.path("items"))audit.record("logistics.batch-import","logistics-version",item.path("versionId").asText(),"success",Map.of("providerId",providerId,"channelId",item.path("channelId").asText(),"file",item.path("fileName").asText(),"action",item.path("action").asText()));return ApiResponse.ok(result);}
    @PostMapping("/providers/{providerId}/versions/publish-batch")ApiResponse<?>publishProviderVersions(@PathVariable UUID providerId,@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){body.put("providerId",providerId.toString());var existing=idempotency.existing(account(auth),"logistics-provider-batch-publish",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.publishProviderBatch(providerId,(tools.jackson.databind.node.ArrayNode)body.withArray("selections"),body.path("note").asText(),account(auth));idempotency.save(account(auth),"logistics-provider-batch-publish",key,body,result);for(var version:result.path("published"))audit.record("logistics.batch-publish","logistics-version",version.path("id").asText(),"success",Map.of("providerId",providerId,"channelId",version.path("channelId").asText()));return ApiResponse.ok(result);}
    @PostMapping("/channels/{channelId}/versions/{versionId}/reject")ApiResponse<?>rejectVersion(@PathVariable UUID channelId,@PathVariable UUID versionId,@RequestBody ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){body.put("channelId",channelId.toString()).put("versionId",versionId.toString());var existing=idempotency.existing(account(auth),"logistics-version-reject",key,body);if(existing.isPresent())return ApiResponse.ok(existing.get());var result=logistics.rejectDraft(channelId,versionId,body.path("note").asText(),account(auth));idempotency.save(account(auth),"logistics-version-reject",key,body,result);audit.record("logistics.reject","logistics-version",versionId.toString(),"success",Map.of("channelId",channelId,"note",body.path("note").asText()));return ApiResponse.ok(result);}
    @PostMapping("/channels/{channelId}/versions/{versionId}/publish")ApiResponse<?>publish(@PathVariable UUID channelId,@PathVariable UUID versionId,@RequestBody(required=false)ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){var request=body==null?tools.jackson.databind.node.JsonNodeFactory.instance.objectNode():body;request.put("channelId",channelId.toString()).put("versionId",versionId.toString());var existing=idempotency.existing(account(auth),"logistics-publish",key,request);if(existing.isPresent())return ApiResponse.ok(existing.get());var note=request.path("note").asText("");var result=logistics.publish(channelId,versionId,note,account(auth),request.path("removalConfirmed").asBoolean(false));idempotency.save(account(auth),"logistics-publish",key,request,result);audit.record("logistics.publish","logistics-version",versionId.toString(),"success",Map.of("channelId",channelId));return ApiResponse.ok(result);}
    @PostMapping("/channels/{channelId}/versions/{versionId}/rollback")ApiResponse<?>rollback(@PathVariable UUID channelId,@PathVariable UUID versionId,@RequestBody(required=false)ObjectNode body,@RequestHeader("Idempotency-Key")String key,Authentication auth){var request=body==null?tools.jackson.databind.node.JsonNodeFactory.instance.objectNode():body;request.put("channelId",channelId.toString()).put("versionId",versionId.toString());var existing=idempotency.existing(account(auth),"logistics-rollback",key,request);if(existing.isPresent())return ApiResponse.ok(existing.get());var note=request.path("note").asText("");var result=logistics.rollback(channelId,versionId,note,account(auth));idempotency.save(account(auth),"logistics-rollback",key,request,result);audit.record("logistics.rollback","logistics-version",result.path("id").asText(),"success",Map.of("channelId",channelId,"targetVersionId",versionId));return ApiResponse.ok(result);}
    private ObjectNode previewBatch(UUID providerId,List<MultipartFile> files){if(files==null||files.isEmpty())throw com.milano.quotation.common.AppException.unprocessable("请选择至少一个物流模板");if(files.size()>100)throw com.milano.quotation.common.AppException.unprocessable("单次最多导入100个物流模板");var result=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("providerId",providerId.toString());var items=result.putArray("items");var claimed=new java.util.HashSet<String>();for(var file:files){var initial=workbooks.parse(file,tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode());var match=logistics.matchProviderFile(providerId,initial.path("fileName").asText(),initial.path("sourceHash").asText());var channelId=match.path("channelId").asText();var parsed=channelId.isBlank()?initial:workbooks.parse(file,logistics.publishedRows(UUID.fromString(channelId)));parsed.setAll(match);var claim=channelId.isBlank()?match.path("channelCode").asText():channelId;if(!claimed.add(claim))throw com.milano.quotation.common.AppException.conflict("同一批次中一个渠道只能对应一个文件："+file.getOriginalFilename());items.add(parsed);}result.put("count",items.size()).put("blocking",java.util.stream.StreamSupport.stream(items.spliterator(),false).mapToInt(item->item.path("errors").asInt()>0?1:0).sum());return result;}
    private static String account(Authentication auth){return ((QuotationPrincipal)auth.getPrincipal()).account();}
}
